pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface GOLDENREGENTINVESTMENT {
    function owner() external view returns (address);
    function setSwapAndLiquifyEnabled(bool e) external;
    function _swapAndLiquifyEnabled() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x134C857757308AEeC4c20CA2A583F560a906ed28;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use the already deployed contract at TARGET
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner address
        address ownerAddress = GOLDENREGENTINVESTMENT(TARGET).owner();

        // Impersonate the owner and call setSwapAndLiquifyEnabled(false)
        vm.prank(ownerAddress);
        GOLDENREGENTINVESTMENT(TARGET).setSwapAndLiquifyEnabled(false);

        // Verify the exploit worked
        bool swapEnabled = GOLDENREGENTINVESTMENT(TARGET)._swapAndLiquifyEnabled();
        require(swapEnabled == false, "Exploit failed: swapAndLiquifyEnabled is not false");
        assertEq(swapEnabled, false, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

